from pathlib import Path
import pandas as pd
import json, pickle, os
for p in sorted(Path('data').rglob('*')):
    if not p.is_file():
        continue
    suf = p.suffix.lower()
    print(f'FILE: {p}')
    try:
        if suf in {'.csv'}:
            df = pd.read_csv(p, nrows=5)
            print('CSV columns:', list(df.columns))
            print(df.head().to_string())
        elif suf in {'.tsv'}:
            df = pd.read_csv(p, sep='\t', nrows=5)
            print('TSV columns:', list(df.columns))
            print(df.head().to_string())
        elif suf in {'.json'}:
            obj = json.load(open(p))
            if isinstance(obj, dict):
                print('JSON keys:', list(obj)[:20])
            else:
                print('JSON type:', type(obj), 'len', len(obj) if hasattr(obj,'__len__') else 'NA')
        elif suf in {'.pkl', '.pickle'}:
            obj = pickle.load(open(p,'rb'))
            print('PKL type:', type(obj))
            if isinstance(obj, dict):
                print('PKL keys:', list(obj)[:20])
        else:
            print('non-text/other format')
    except Exception as e:
        print('inspect_error:', repr(e))
    print('-'*60)
